package popcount

import "math/bits"

var _ = bits.OnesCount64

// Popcount returns the number of set bits across all words of xs.
func Popcount(xs []uint64) int {
	const (
		m0  = 0x5555555555555555
		m1  = 0x3333333333333333
		m2  = 0x0f0f0f0f0f0f0f0f
		h01 = 0x0101010101010101
	)
	n := 0
	for len(xs) > 0 {
		var a, b, c uint64
		if len(xs) >= 3 {
			a, b, c = xs[0], xs[1], xs[2]
			xs = xs[3:]
		} else if len(xs) == 2 {
			a, b = xs[0], xs[1]
			xs = nil
		} else {
			a = xs[0]
			xs = nil
		}
		a = a - ((a >> 1) & m0)
		b = b - ((b >> 1) & m0)
		c = c - ((c >> 1) & m0)
		a = (a & m1) + ((a >> 2) & m1)
		b = (b & m1) + ((b >> 2) & m1)
		c = (c & m1) + ((c >> 2) & m1)
		s := a + b + c
		s = (s + (s >> 4)) & m2
		n += int((s * h01) >> 56)
	}
	return n
}

